ledger_t lg;
ledger_init(&lg);
CHECK_EQ(ledger_acquire(&lg, 7), 1);
CHECK_EQ(ledger_acquire(&lg, 9), 1);
CHECK_EQ(ledger_live(&lg), 2);
CHECK_EQ(ledger_release(&lg, 7), 1);
CHECK_EQ(ledger_live(&lg), 1);
CHECK_EQ(ledger_release(&lg, 7), 0);

ledger_t lg;
ledger_init(&lg);
CHECK_EQ(ledger_acquire(&lg, 5), 1);
CHECK_EQ(ledger_acquire(&lg, 5), 0);
CHECK_EQ(ledger_live(&lg), 1);

ledger_t lg;
ledger_init(&lg);
for (int i = 0; i < LEDGER_CAP; i++) CHECK_EQ(ledger_acquire(&lg, i + 1), 1);
CHECK_EQ(ledger_acquire(&lg, 99), -1);
CHECK_EQ(ledger_live(&lg), LEDGER_CAP);

ledger_t lg;
ledger_init(&lg);
CHECK_EQ(ledger_audit(&lg), 1);
ledger_acquire(&lg, 3);
CHECK_EQ(ledger_audit(&lg), 1);
lg.ids[1] = 3;
lg.count = 2;
CHECK_EQ(ledger_audit(&lg), 0);
